    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_termoak_ffi_fn_free_serverterminallistener(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_termoak_ffi_fn_clone_serverterminallistener(handle, status)
        }
    }

    override fun `onEvent`(`event`: ServerTerminalEvent)
        = 
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_termoak_ffi_fn_method_serverterminallistener_on_event(
        it,
        
        FfiConverterTypeServerTerminalEvent.lower(`event`),_status)
}
    }
    
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}



