public object FfiConverterTypeServerTerminalListener: FfiConverter<ServerTerminalListener, Long> {
    internal val handleMap = UniffiHandleMap<ServerTerminalListener>()

    override fun lower(value: ServerTerminalListener): Long {
        if (value is ServerTerminalListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): ServerTerminalListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ServerTerminalListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): ServerTerminalListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ServerTerminalListener) = 8UL

    override fun write(value: ServerTerminalListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


