/**
 * Local SSH connection to a host. Terminals, SFTP, tunnels and commands are
 * opened over it. It is closed with [`SshSession::disconnect`] or when all
 * its references are dropped (including terminals and tunnels).
 */
public interface SshSessionInterface {
    
    fun `details`(): ConnectionDetails
    
    /**
     * Detects the remote system (`ubuntu`, `debian`, `alpine`, `freebsd`,
     * `macos`, `windows`...) and stores it in the host to show its icon.
     * See [`detect_os_info`](Self::detect_os_info) for the version and the
     * full name.
     */
    suspend fun `detectOs`(): kotlin.String?
    
    /**
     * Detects the remote system with its version and display name
     * (`Ubuntu 24.04.1 LTS`), like Termius does, and stores it in the host
     * (`os` and `os_version`).
     */
    suspend fun `detectOsInfo`(): RemoteOs?
    
    /**
     * Closes the connection (and with it its terminals, SFTP and tunnels).
     */
    suspend fun `disconnect`()
    
    /**
     * Runs a non-interactive command and waits for it to finish.
     */
    suspend fun `exec`(`command`: kotlin.String, `timeoutSecs`: kotlin.UInt): ExecResult
    
    /**
     * Host it is connected to.
     */
    fun `hostId`(): kotlin.String
    
    fun `isClosed`(): kotlin.Boolean
    
    /**
     * Opens a terminal (PTY with a shell) with the host's effective settings
     * (TERM, variables, startup snippet...). `record` forces recording
     * (asciicast in `<data_dir>/recordings`).
     */
    suspend fun `openTerminal`(`cols`: kotlin.UInt, `rows`: kotlin.UInt, `listener`: TerminalListener, `record`: kotlin.Boolean = false): TerminalHandle
    
    /**
     * Changes the permissions (e.g. `0o644`).
     */
    suspend fun `sftpChmod`(`path`: kotlin.String, `mode`: kotlin.UInt)
    
    /**
     * Downloads `remote_path` to `local_path` (a file on the device).
     * Returns the bytes copied.
     */
    suspend fun `sftpDownload`(`remotePath`: kotlin.String, `localPath`: kotlin.String, `listener`: TransferListener?): kotlin.ULong
    
    /**
     * The user's home directory.
     */
    suspend fun `sftpHome`(): kotlin.String
    
    /**
     * Lists a directory: folders first, then by name.
     */
    suspend fun `sftpList`(`path`: kotlin.String): List<RemoteFile>
    
    /**
     * Creates a directory (with `recursive`, also any missing parents).
     */
    suspend fun `sftpMkdir`(`path`: kotlin.String, `recursive`: kotlin.Boolean)
    
    /**
     * Reads a whole file into memory (for editors and viewers).
     */
    suspend fun `sftpRead`(`path`: kotlin.String, `maxBytes`: kotlin.ULong): kotlin.ByteArray
    
    /**
     * Deletes a file or a directory (with `recursive`, with its contents).
     */
    suspend fun `sftpRemove`(`path`: kotlin.String, `recursive`: kotlin.Boolean)
    
    /**
     * Renames or moves.
     */
    suspend fun `sftpRename`(`from`: kotlin.String, `to`: kotlin.String)
    
    suspend fun `sftpStat`(`path`: kotlin.String): RemoteFile
    
    /**
     * Uploads `local_path` (a file on the device) to `remote_path`.
     * Returns the bytes copied.
     */
    suspend fun `sftpUpload`(`localPath`: kotlin.String, `remotePath`: kotlin.String, `listener`: TransferListener?): kotlin.ULong
    
    /**
     * Writes (creates or overwrites) a file.
     */
    suspend fun `sftpWrite`(`path`: kotlin.String, `data`: kotlin.ByteArray)
    
    /**
     * Starts the host's tunnels marked `auto_start`. Those that fail are
     * skipped (and the error is logged).
     */
    suspend fun `startAutoForwards`(): List<ActiveForward>
    
    /**
     * Starts a tunnel saved in the vault.
     */
    suspend fun `startForward`(`forwardId`: kotlin.String): ActiveForward
    
    /**
     * Starts an ad hoc tunnel (without saving it). `bind_port` 0 = free port.
     */
    suspend fun `startForwardSpec`(`kind`: ForwardKind, `bindAddress`: kotlin.String, `bindPort`: kotlin.UInt, `destHost`: kotlin.String?, `destPort`: kotlin.UInt?): ActiveForward
    
    companion object
}

