    suspend fun `adminUpdateUser`(`userId`: kotlin.String, `name`: kotlin.String?, `isAdmin`: kotlin.Boolean?, `disabled`: kotlin.Boolean?): ServerUser
    
    /**
     * Creates a team (you will be its owner).
     */
    suspend fun `createTeam`(`name`: kotlin.String): Team
    
    /**
