     */
    suspend fun `removeTeamMember`(`teamId`: kotlin.String, `userId`: kotlin.String)
    
    /**
     * Renames a team (team owners and admins).
     */
    suspend fun `renameTeam`(`teamId`: kotlin.String, `name`: kotlin.String): Team
    
    /**
