/**
 * What the device that shares a terminal hears from the server.
 */
sealed class SharedTerminalEvent {
    
    /**
     * Who is in the session and who drives (`None`: you).
     */
    data class Participants(
        val `participants`: List<com.termoak.ffi.SessionParticipant>, 
        val `driver`: kotlin.String?) : SharedTerminalEvent()
        
    {
        

        companion object
    }
    
    /**
     * The keyboard changed hands. `until`: when a timed grant ends (ms).
     */
    data class Control(
        val `driver`: kotlin.String?, 
        val `driverName`: kotlin.String?, 
        val `until`: kotlin.Long?) : SharedTerminalEvent()
        
    {
        

        companion object
    }
    
    /**
     * A timed grant ended: the keyboard is yours again
     * (`participant_id`: who had it).
     */
    data class ControlExpired(
        val `participantId`: kotlin.String?) : SharedTerminalEvent()
        
    {
        

        companion object
    }
    
    /**
