    object Reconnected : SharedTerminalEvent()
    
    
    /**
     * Sharing ended (`code` if the server said why). Nothing else arrives.
     */
    data class Ended(
        val `code`: kotlin.String?) : SharedTerminalEvent()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

