/**
 * Termoak error as seen from Swift (`TermoakError`) and Kotlin
 * (`TermoakException`).
 *
 * It is a "flat" error: each variant only carries the message, in English
 * and ready to show; the variant tells the app what to do (e.g. ask for the
 * login again on `SessionExpired`).
 */
sealed class TermoakException(message: String): kotlin.Exception(message) {
        
    /**
     * Invalid data (empty required field, malformed id, unreadable SSH key...).
     */
        class Invalid(message: String) : TermoakException(message)
        
    /**
     * The record does not exist (or is not yours).
     */
        class NotFound(message: String) : TermoakException(message)
        
    /**
     * Conflict with another record.
     */
        class Conflict(message: String) : TermoakException(message)
        
    /**
     * You are not allowed to do that.
     */
        class Forbidden(message: String) : TermoakException(message)
        
    /**
     * Vault: wrong key or tampered data.
     */
        class Vault(message: String) : TermoakException(message)
        
    /**
     * Not signed in to any server.
     */
        class NotLoggedIn(message: String) : TermoakException(message)
        
    /**
     * The session expired or was revoked: sign in again.
     */
        class SessionExpired(message: String) : TermoakException(message)
        
    /**
     * The account has two-factor authentication: ask for the code and call
     * `login` again with it.
     */
        class TotpRequired(message: String) : TermoakException(message)
        
    /**
     * The two-factor authentication code is wrong.
     */
        class TotpInvalid(message: String) : TermoakException(message)
        
    /**
     * The server returned an error (the message includes the HTTP status).
     */
        class Server(message: String) : TermoakException(message)
        
    /**
     * Network error (offline, DNS, TLS, WebSocket...).
     */
        class Network(message: String) : TermoakException(message)
        
    /**
     * Could not connect over SSH (network, timeout, negotiation, channel).
     */
        class Connection(message: String) : TermoakException(message)
        
    /**
     * The SSH server's key changed, is unknown or was rejected.
     */
        class HostKey(message: String) : TermoakException(message)
        
    /**
     * SSH authentication failed.
     */
        class Auth(message: String) : TermoakException(message)
        
    /**
     * An SFTP operation failed.
     */
        class Sftp(message: String) : TermoakException(message)
        
    /**
     * The connection, terminal or tunnel is already closed.
     */
        class Closed(message: String) : TermoakException(message)
        
    /**
     * Local I/O error (device files).
     */
        class Io(message: String) : TermoakException(message)
        
    /**
     * Unexpected internal error.
     */
        class Internal(message: String) : TermoakException(message)
        
    /**
     * The plan does not include the server's AI and there is no API key of
     * your own that can be used: show "add your API key in Settings → AI"
     * (`set_ai_key`).
     */
        class AiKeyRequired(message: String) : TermoakException(message)
        
    /**
     * This month's AI credit for the server's providers is spent (your own
     * API keys keep working).
     */
        class AiBudgetExceeded(message: String) : TermoakException(message)
        
    /**
     * The server requires a verified email and this account has not
     * verified it yet: show the screen to enter the six-digit code from the
     * email (`verify_code`, `resend_code`). The account's email is
     * `server_user`.
     */
        class EmailNotVerified(message: String) : TermoakException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TermoakException> {
        override fun lift(error_buf: RustBuffer.ByValue): TermoakException = FfiConverterTypeTermoakError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeTermoakError : FfiConverterRustBuffer<TermoakException> {
    override fun read(buf: ByteBuffer): TermoakException {
        
            return when(buf.getInt()) {
            1 -> TermoakException.Invalid(FfiConverterString.read(buf))
            2 -> TermoakException.NotFound(FfiConverterString.read(buf))
            3 -> TermoakException.Conflict(FfiConverterString.read(buf))
            4 -> TermoakException.Forbidden(FfiConverterString.read(buf))
            5 -> TermoakException.Vault(FfiConverterString.read(buf))
            6 -> TermoakException.NotLoggedIn(FfiConverterString.read(buf))
            7 -> TermoakException.SessionExpired(FfiConverterString.read(buf))
            8 -> TermoakException.TotpRequired(FfiConverterString.read(buf))
            9 -> TermoakException.TotpInvalid(FfiConverterString.read(buf))
            10 -> TermoakException.Server(FfiConverterString.read(buf))
            11 -> TermoakException.Network(FfiConverterString.read(buf))
            12 -> TermoakException.Connection(FfiConverterString.read(buf))
            13 -> TermoakException.HostKey(FfiConverterString.read(buf))
            14 -> TermoakException.Auth(FfiConverterString.read(buf))
            15 -> TermoakException.Sftp(FfiConverterString.read(buf))
            16 -> TermoakException.Closed(FfiConverterString.read(buf))
            17 -> TermoakException.Io(FfiConverterString.read(buf))
            18 -> TermoakException.Internal(FfiConverterString.read(buf))
            19 -> TermoakException.AiKeyRequired(FfiConverterString.read(buf))
            20 -> TermoakException.AiBudgetExceeded(FfiConverterString.read(buf))
            21 -> TermoakException.EmailNotVerified(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: TermoakException): ULong {
        return 4UL
    }

    override fun write(value: TermoakException, buf: ByteBuffer) {
        when(value) {
            is TermoakException.Invalid -> {
                buf.putInt(1)
                Unit
            }
            is TermoakException.NotFound -> {
                buf.putInt(2)
                Unit
            }
            is TermoakException.Conflict -> {
                buf.putInt(3)
                Unit
            }
            is TermoakException.Forbidden -> {
                buf.putInt(4)
                Unit
            }
            is TermoakException.Vault -> {
                buf.putInt(5)
                Unit
            }
            is TermoakException.NotLoggedIn -> {
                buf.putInt(6)
                Unit
            }
            is TermoakException.SessionExpired -> {
                buf.putInt(7)
                Unit
            }
            is TermoakException.TotpRequired -> {
                buf.putInt(8)
                Unit
            }
            is TermoakException.TotpInvalid -> {
                buf.putInt(9)
                Unit
            }
            is TermoakException.Server -> {
                buf.putInt(10)
                Unit
            }
            is TermoakException.Network -> {
                buf.putInt(11)
                Unit
            }
            is TermoakException.Connection -> {
                buf.putInt(12)
                Unit
            }
            is TermoakException.HostKey -> {
                buf.putInt(13)
                Unit
            }
            is TermoakException.Auth -> {
                buf.putInt(14)
                Unit
            }
            is TermoakException.Sftp -> {
                buf.putInt(15)
                Unit
            }
            is TermoakException.Closed -> {
                buf.putInt(16)
                Unit
            }
            is TermoakException.Io -> {
                buf.putInt(17)
                Unit
            }
            is TermoakException.Internal -> {
                buf.putInt(18)
                Unit
            }
            is TermoakException.AiKeyRequired -> {
                buf.putInt(19)
                Unit
            }
            is TermoakException.AiBudgetExceeded -> {
                buf.putInt(20)
                Unit
            }
            is TermoakException.EmailNotVerified -> {
                buf.putInt(21)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




